<?php require_once "../config/auth.php";require_login();$u=user();$err="";$ok="";if($_SERVER["REQUEST_METHOD"]==="POST"){check_csrf();$a=(float)$_POST["amount"];$m=trim($_POST["method"]);$ac=trim($_POST["account"]);if($a<100||strlen($ac)<4)$err="Minimum withdrawal is ৳100.";else{$pdo=db();$pdo->beginTransaction();try{$q=$pdo->prepare("SELECT balance FROM users WHERE id=? FOR UPDATE");$q->execute([$u["id"]]);if((float)$q->fetchColumn()<$a)throw new Exception("Insufficient balance.");$pdo->prepare("UPDATE users SET balance=balance-? WHERE id=?")->execute([$a,$u["id"]]);$pdo->prepare("INSERT INTO withdrawals(user_id,amount,method,account) VALUES(?,?,?,?)")->execute([$u["id"],$a,$m,$ac]);$pdo->prepare("INSERT INTO transactions(user_id,type,amount,description) VALUES(?,'withdrawal',?,'Withdrawal request')")->execute([$u["id"],-$a]);$pdo->commit();$ok="Withdrawal submitted.";}catch(Exception $x){$pdo->rollBack();$err=$x->getMessage();}}}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="style.css"></head><body><main><form class="box" method="post"><h1>Withdraw</h1><?php if($err):?><div class="error"><?=e($err)?></div><?php endif;?><?php if($ok):?><div class="success"><?=$ok?></div><?php endif;?><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input name="amount" type="number" min="100" placeholder="Amount (minimum ৳100)" required><select name="method"><option>bKash</option><option>Nagad</option></select><input name="account" placeholder="Payment account" required><button>Request Withdrawal</button></form></main></body></html>